                registration date's year, e.g. 'SYD-SMI-0007-M26'. Absent when the owner has no
                customer code or registration date.
              type: string
              example: 'MAD-FRA-0002-M20'
              readOnly: true
            membershipTier:
              title: Membership tier
              description: >-
                Assigned on create: 'GOLD' when the owner's household (owners sharing the same
                'householdId') has 3 or more members after this owner is created; otherwise 'SILVER'
                when 'namesakeCount' is 0 and an email is present, otherwise 'BRONZE'.
              type: string
              example: 'SILVER'
              readOnly: true
            locality:
              title: Locality
              description: >-
                The region derived from the city using the fixed table Sydney -> 'NSW',
                Melbourne -> 'VIC', Brisbane -> 'QLD'; 'UNKNOWN' for any other city.
              type: string
              example: 'NSW'
              readOnly: true
            bulkSignupWarning:
              title: Bulk signup warning
              description: >-
                Assigned on create: true when more than 80 owners had already been created for the
                same (business-day adjusted) registration date before this owner, otherwise false.
              type: boolean
              example: false
              readOnly: true
          required:
            - pets
